// Typed access to the asset registry generated by `pnpm models:build`.
// To add or change a model, edit assets/models/<id>/model.json — never this data.
import registry from '@/generated/model-registry.json'

export interface Credit {
  author: string | null
  license: string
  source: string | null
}

export interface MaterialOverride {
  color?: string
  metalness?: number
  roughness?: number
  clearcoat?: number
  clearcoatRoughness?: number
  opacity?: number
}

export interface PaintPreset {
  name: string
  hex: string
}

export interface StudioConfig {
  lengthM: number
  // Direction the car's nose points in model space
  forward: '+x' | '-x' | '+z' | '-z'
  materials?: Record<string, MaterialOverride>
  paint?: { materials: string[]; presets: PaintPreset[] }
  lights?: { head?: string[]; tail?: string[] }
}

export interface ModelEntry {
  id: string
  path: string
  title: string
  credit: Credit
  match: string[]
  studio: StudioConfig | null
}

export interface EnvironmentEntry {
  id: string
  path: string
  title: string
  credit: Credit
}

const MODELS: ModelEntry[] = Object.entries(registry.models as Record<string, Omit<ModelEntry, 'id'>>).map(
  ([id, m]) => ({ id, ...m }),
)
const ENVIRONMENTS: EnvironmentEntry[] = Object.entries(
  registry.environments as Record<string, Omit<EnvironmentEntry, 'id'>>,
).map(([id, e]) => ({ id, ...e }))

export const STUDIO_ENVIRONMENT = ENVIRONMENTS.find((e) => e.id === 'studio-small-09') ?? null

export function getModel(id: string): ModelEntry | null {
  return MODELS.find((m) => m.id === id) ?? null
}

export function modelPath(id: string): string {
  const model = getModel(id)
  if (!model) throw new Error(`Unknown model id "${id}"`)
  return model.path
}

// Longest alias wins, so "bmw m4 competition" beats "bmw m4"
export function findModelForVehicle(make: string, model: string): ModelEntry | null {
  const key = `${make} ${model}`.toLowerCase().trim()
  let best: { entry: ModelEntry; length: number } | null = null
  for (const entry of MODELS) {
    for (const alias of entry.match) {
      if (key.includes(alias) && alias.length > (best?.length ?? 0)) best = { entry, length: alias.length }
    }
  }
  return best?.entry ?? null
}

// Only models that meet the realism bar have a studio config
export function getStudioModel(make: string, model: string): ModelEntry | null {
  const entry = findModelForVehicle(make, model)
  return entry?.studio ? entry : null
}

export function listCredits(): { title: string; credit: Credit }[] {
  return [...MODELS, ...ENVIRONMENTS].map(({ title, credit }) => ({ title, credit }))
}